ALTER TABLE public.learning_modules ADD COLUMN notes_origin text NOT NULL DEFAULT 'human';
CREATE FUNCTION public.curriculum_import_notes(p_topics jsonb) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE m uuid; t jsonb; previous text:=NULL; pos integer:=0; BEGIN IF auth.uid() IS NULL OR NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'Forbidden'; END IF; IF jsonb_typeof(p_topics) IS DISTINCT FROM 'array' OR jsonb_array_length(p_topics)<>10 THEN RAISE EXCEPTION 'Ten draft notes required'; END IF; PERFORM pg_advisory_xact_lock(hashtextextended('python-curriculum-import',0)); SELECT id INTO m FROM public.learning_modules WHERE slug='python-fundamentals'; IF m IS NOT NULL THEN RETURN m; END IF;
INSERT INTO public.learning_modules(slug,title,notes_origin) VALUES('python-fundamentals','Python Fundamentals','AI-authored draft notes; independent review required') RETURNING id INTO m;
FOR t IN SELECT value FROM jsonb_array_elements(p_topics) LOOP pos:=pos+1; IF jsonb_typeof(t->'notes') IS DISTINCT FROM 'object' THEN RAISE EXCEPTION 'Invalid notes'; END IF; INSERT INTO public.learning_topics(id,module_id,title,position,prerequisite,estimated_minutes) VALUES(t->>'id',m,t->>'title',pos,previous,(t->>'minutes')::integer); INSERT INTO public.learning_notes(topic_id,content) VALUES(t->>'id',t->'notes'); previous:=t->>'id'; END LOOP; RETURN m; END $$;
REVOKE ALL ON FUNCTION public.curriculum_import_notes(jsonb) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.curriculum_import_notes(jsonb) TO authenticated,service_role;
CREATE OR REPLACE FUNCTION public.topic_activity_record(p_topic text,p_event uuid) RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE s public.student_learning_sessions; elapsed integer; BEGIN IF p_event IS NULL OR NOT public.curriculum_topic_allowed(p_topic) THEN RAISE EXCEPTION 'Forbidden'; END IF;
PERFORM pg_advisory_xact_lock(hashtextextended(auth.uid()::text||'time',0)); SELECT * INTO s FROM public.student_learning_sessions WHERE user_id=auth.uid() AND topic_id=p_topic FOR UPDATE;
IF s.id IS NULL THEN INSERT INTO public.student_learning_sessions(user_id,topic_id,last_event) VALUES(auth.uid(),p_topic,p_event); RETURN 0; END IF;
IF s.last_event=p_event THEN RETURN s.active_seconds; END IF;
SELECT greatest(0,floor(extract(epoch FROM now()-max(last_at))))::integer INTO elapsed FROM public.student_learning_sessions WHERE user_id=auth.uid();
UPDATE public.student_learning_sessions SET last_event=p_event,last_at=now(),active_seconds=active_seconds+CASE WHEN elapsed BETWEEN 5 AND 40 THEN elapsed ELSE 0 END WHERE id=s.id RETURNING active_seconds INTO elapsed; RETURN elapsed; END $$;
COMMENT ON TABLE public.topic_quiz_questions IS 'Predefined human-authored topic questions only; not AI generated. Admin review required before approved use; keys never exposed to learners before submission.';